 12	static wide_t min_w(wide_t a, wide_t b) { return a < b ? a : b; }
 13	static wide_t max_w(wide_t a, wide_t b) { return a > b ? a : b; }
 14	static wide_t clamp_w(wide_t v, wide_t lo, wide_t hi) {
 15	  return v < lo ? lo : v > hi ? hi : v;
 16	}
