110	      if ((yi < sy && yj >= sy) || (yj < sy && yi >= sy)) {
111	        const float x = pts[i][0] + (sy - yi) / (yj - yi) * (pts[j][0] - pts[i][0]);
112	        xl = fminf(xl, x);
113	        xr = fmaxf(xr, x);
114	      }
115	    }
116	    if (xl > xr) continue;
117	    fill_box(c, (wide_t)floorf(xl - 0.5f) + 1, y, (wide_t)floorf(xr - 0.5f), y,
118	             colour);
119	  }
120	}
121	
122	/* Where a vertex's line runs, in pixel coordinates (see stroke.h). */
123	static float centre_offset(int w) { return (w & 1) ? 0.5f : 0.0f; }
124	
125	static vec2 vertex(int x, int y, int w) {
126	  const float o = centre_offset(w);
127	  return (vec2){(float)x + o, (float)y + o};
128	}
129	
130	/* A segment between two vertices already in pixel coordinates, as a quad. An
131	 * end with a cap is lengthened enough to cover the pixel at the vertex (half a
132	 * pixel on an axis-aligned line; up to 0.71 on a diagonal when the width is
133	 * even and the vertex is a pixel corner), and by half the width more for a
134	 * projecting cap. An end that meets another segment (STROKE_NO_CAP) is not
135	 * lengthened at all. */
136	static void segment_quad(Canvas *c, vec2 a, vec2 b, int cap1, int cap2, int w,
137	                         uint16_t colour) {
138	  const float dx = b.x - a.x, dy = b.y - a.y;
139	  const float len = sqrtf(dx * dx + dy * dy);
140	  if (len < 0.001f) return;
141	  const float ux = dx / len, uy = dy / len;
142	  const float half = (float)w / 2.0f;
143	  const float pixel_along = (0.5f - centre_offset(w)) * (ux + uy);
144	  const float e1 = cap1 == STROKE_NO_CAP ? 0.0f
145	                   : fmaxf(0.5f, -pixel_along) + (cap1 == CapProjecting ? half : 0.0f);
146	  const float e2 = cap2 == STROKE_NO_CAP ? 0.0f
147	                   : fmaxf(0.5f, pixel_along) + (cap2 == CapProjecting ? half : 0.0f);
148	  const float nx = -uy * half, ny = ux * half;
149	  const vec2 p = {a.x - ux * e1, a.y - uy * e1};
150	  const vec2 q = {b.x + ux * e2, b.y + uy * e2};
151	  const float quad[4][2] = {
152	      {p.x + nx, p.y + ny}, {q.x + nx, q.y + ny}, {q.x - nx, q.y - ny},
153	      {p.x - nx, p.y - ny}};
154	  fill_convex(c, quad, 4, colour);
155	}
156	
157	/* One slanted segment whose ends can be anywhere in the int range. Ends cut by
158	 * the clip are off screen anyway. */
159	static void slanted(Canvas *c, wide_t ix1, wide_t iy1, wide_t ix2, wide_t iy2,
160	                    int cap1, int cap2, int w, uint16_t colour) {
161	  double x1 = (double)ix1, y1 = (double)iy1, x2 = (double)ix2, y2 = (double)iy2;
162	  if (!clip_to_canvas(c, (wide_t)w + 2, &x1, &y1, &x2, &y2)) return;
163	  const float o = centre_offset(w);
164	  segment_quad(c, (vec2){(float)x1 + o, (float)y1 + o},
165	               (vec2){(float)x2 + o, (float)y2 + o}, cap1, cap2, w, colour);
166	}
167	
168	void stroke_segment_ends(Canvas *c, const struct XshimGC *gc, int x1, int y1,
169	                         int x2, int y2, int cap_start, int cap_end) {
170	  const int w = gc->line_width;
171	  const uint16_t colour = (uint16_t)gc->foreground;
172	
173	  if (cap_start == CapRound) disc(c, x1, y1, w, colour);
174	  if (cap_end == CapRound) disc(c, x2, y2, w, colour);
175	
176	  if (x1 == x2 && y1 == y2) {
177	    if (cap_start == CapProjecting || cap_end == CapProjecting)
178	      axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
179	    return;
180	  }
181	  if (x1 == x2 || y1 == y2)
182	    axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
183	  else
184	    slanted(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
185	}
186	
187	void stroke_segment(Canvas *c, const struct XshimGC *gc, int x1, int y1, int x2,
188	                    int y2) {
189	  stroke_segment_ends(c, gc, x1, y1, x2, y2, gc->cap_style, gc->cap_style);
190	}
191	
192	/* The corner between a segment arriving along d1 and one leaving along d2
193	 * (unit vectors), at vertex (ix, iy). */
194	static void join_at(Canvas *c, int ix, int iy, vec2 d1, vec2 d2, int w,
195	                    int style, uint16_t colour) {
196	  const float dot = d1.x * d2.x + d1.y * d2.y;
197	  const float cross = d1.x * d2.y - d1.y * d2.x;
198	  if (fabsf(cross) < 1e-4f && dot > 0) return;
199	  if (style == JoinRound) {
200	    disc(c, ix, iy, w, colour);
201	    return;
202	  }
203	  const vec2 v = vertex(ix, iy, w);
204	  const float half = (float)w / 2.0f;
205	  const float side = cross > 0 ? -1.0f : 1.0f;
206	  const vec2 n1 = {-d1.y * side, d1.x * side}, n2 = {-d2.y * side, d2.x * side};
207	  const vec2 p1 = {v.x + n1.x * half, v.y + n1.y * half};
208	  const vec2 p2 = {v.x + n2.x * half, v.y + n2.y * half};
209	  /* Xlib's miter limit of 10: the miter is longer than ten widths when the
210	   * segments meet at less than about 11.5 degrees, i.e. dot < -0.98. */
211	  if (style == JoinMiter && dot >= -0.98f) {
212	    const float k = half / (1.0f + dot);
213	    const float quad[4][2] = {{v.x, v.y},
214	                              {p1.x, p1.y},
215	                              {v.x + (n1.x + n2.x) * k, v.y + (n1.y + n2.y) * k},
216	                              {p2.x, p2.y}};
217	    fill_convex(c, quad, 4, colour);
218	    return;
219	  }
220	  const float tri[3][2] = {{v.x, v.y}, {p1.x, p1.y}, {p2.x, p2.y}};
221	  fill_convex(c, tri, 3, colour);
222	}
223	
224	static vec2 direction(const int *from, const int *to) {
225	  const float dx = (float)((wide_t)to[0] - from[0]);
226	  const float dy = (float)((wide_t)to[1] - from[1]);
227	  const float len = sqrtf(dx * dx + dy * dy);
228	  return (vec2){dx / len, dy / len};
229	}
230	
231	void stroke_polyline(Canvas *c, const struct XshimGC *gc, const int *xy, int n,
232	                     int closed) {
233	  if (n <= 0) return;
234	  const int w = gc->line_width;
235	  const uint16_t colour = (uint16_t)gc->foreground;
236	
237	  int stack_v[2 * 64];
238	  int *v = stack_v;
239	  if (n > 64) {
240	    v = (int *)malloc((size_t)n * 2 * sizeof(int));
241	    if (!v) return;
242	  }
243	  int m = 0;
244	  for (int i = 0; i < n; i++) {
245	    if (m > 0 && xy[2 * i] == v[2 * (m - 1)] && xy[2 * i + 1] == v[2 * (m - 1) + 1])
246	      continue;
247	    v[2 * m] = xy[2 * i];
248	    v[2 * m + 1] = xy[2 * i + 1];
249	    m++;
250	  }
251	  if (closed && m > 1 && v[2 * (m - 1)] == v[0] && v[2 * (m - 1) + 1] == v[1]) m--;
252	
253	  if (m == 1 || (m == 2 && !closed)) {
254	    stroke_segment(c, gc, v[0], v[1], v[2 * (m - 1)], v[2 * (m - 1) + 1]);
255	  } else {
256	    const int nseg = closed ? m : m - 1;
257	    for (int i = 0; i < nseg; i++) {
258	      const int *a = v + 2 * i, *b = v + 2 * ((i + 1) % m);
259	      const int cap1 = (!closed && i == 0) ? gc->cap_style : STROKE_NO_CAP;
260	      const int cap2 = (!closed && i == nseg - 1) ? gc->cap_style : STROKE_NO_CAP;
261	      if (cap1 == CapRound) disc(c, a[0], a[1], w, colour);
262	      if (cap2 == CapRound) disc(c, b[0], b[1], w, colour);
263	      segment_quad(c, vertex(a[0], a[1], w), vertex(b[0], b[1], w), cap1, cap2, w,
264	                   colour);
265	    }
266	    const int first = closed ? 0 : 1, last = closed ? m : m - 1;
267	    for (int j = first; j < last; j++) {
268	      const int *prev = v + 2 * ((j + m - 1) % m), *at = v + 2 * j;
269	      const int *next = v + 2 * ((j + 1) % m);
270	      join_at(c, at[0], at[1], direction(prev, at), direction(at, next), w,
271	              gc->join_style, colour);
272	    }
273	  }
274	  if (v != stack_v) free(v);
275	}

