     6	#define FULL_SWEEP (360 * 64)
     7	#define DEGREES_TO_RADIANS 0.017453292519943295f
     8	
     9	static int sweep_of(int angle2) {
    10	  if (angle2 > FULL_SWEEP) return FULL_SWEEP;
    11	  if (angle2 < -FULL_SWEEP) return -FULL_SWEEP;
    12	  return angle2;
    13	}
    14	
    15	/* About one point every two pixels along the larger radius. */
    16	int arc_point_count(unsigned w, unsigned h, int angle2) {
    17	  const int sweep = sweep_of(angle2);
    18	  if (sweep == 0) return 0;
    19	  const float radius = (float)(w > h ? w : h) / 2.0f;
    20	  const float sweep_radians = (float)abs(sweep) / 64.0f * DEGREES_TO_RADIANS;
    21	  const float n = ceilf(sweep_radians * radius / 2.0f) + 1.0f;
    22	  if (n < 2.0f) return 2;
    23	  return n > (float)ARC_MAX_POINTS ? ARC_MAX_POINTS : (int)n;
    24	}
    25	
    26	int arc_points(int x, int y, unsigned w, unsigned h, int angle1, int angle2,
    27	               int *xy, int max_points) {
    28	  int n = arc_point_count(w, h, angle2);
    29	  if (n > max_points) n = max_points;
    30	  if (n < 2) return n < 0 ? 0 : n;
    31	  const float cx = (float)x + (float)w / 2.0f, cy = (float)y + (float)h / 2.0f;
    32	  const float rx = (float)w / 2.0f, ry = (float)h / 2.0f;
    33	  const float start = (float)angle1 / 64.0f * DEGREES_TO_RADIANS;
    34	  const float sweep = (float)sweep_of(angle2) / 64.0f * DEGREES_TO_RADIANS;
    35	  for (int i = 0; i < n; i++) {
    36	    const float a = start + sweep * (float)i / (float)(n - 1);
    37	    xy[2 * i] = (int)lrintf(cx + rx * cosf(a));
    38	    xy[2 * i + 1] = (int)lrintf(cy - ry * sinf(a));
    39	  }
    40	  return n;
    41	}
